const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const HARBORS=[{x:-13,z:8,name:'Copper Quay'},{x:12,z:8,name:'Orchid Reach'},{x:12,z:-9,name:'Bellweather'},{x:-12,z:-9,name:'Moss Lantern'}];
export const CLOUD_ROUTES=['First Post','Crosswind Crossing','Highland Express','Stormlace Run','Midnight Mail','The Last Lighthouse'];
export class Cloudwake{
 constructor({players=1,level=1,difficulty=3}={}){this.level=clamp(Math.round(level),1,6);this.difficulty=clamp(Math.round(difficulty),1,5);this.clock=0;this.limit=350-this.difficulty*25-this.level*6;this.done=false;this.won=false;this.events=[];this.goal=2+Math.ceil(this.level/2);this.players=Array.from({length:players===2?2:1},(_,i)=>({id:i,x:-13+i*1.5,z:8,y:2.2,vx:0,vz:0,vy:0,angle:0,energy:100,hull:3,shield:0,delivered:0,carrying:false,hits:0,rings:0,ringCooldown:0,cooldown:0}));this.obstacles=Array.from({length:4+this.level},(_,i)=>({x:Math.cos(i*2.399+this.level)*7,z:Math.sin(i*2.399+this.level)*6,r:1+(.2*(i%3)),height:3+i%3}));this.storms=Array.from({length:Math.ceil(this.level/2)},(_,i)=>({x:i*7-7,z:(i%2?1:-1)*3,r:1.2+this.difficulty*.12}));this.rings=[{x:0,z:8,y:6},{x:0,z:-9,y:6},{x:12,z:0,y:7}];}
 job(p){const source=(p.delivered+p.id)%4;return{source,destination:(source+1+(this.level>3&&p.delivered%2?1:0))%4};}
 dock(owner){const p=this.players[owner];if(!p||this.done||p.cooldown>0||p.delivered>=this.goal)return false;const job=this.job(p),h=HARBORS[p.carrying?job.destination:job.source];if(Math.hypot(p.x-h.x,p.z-h.z)>2.5||p.y>3.3||Math.hypot(p.vx,p.vz)>3.5)return false;p.cooldown=.6;p.vx=p.vz=0;p.energy=100;p.hull=3;if(p.carrying){p.delivered++;p.carrying=false;this.events.push({type:'delivery',owner,x:p.x,y:p.y,z:p.z});}else{p.carrying=true;this.events.push({type:'pickup',owner,x:p.x,y:p.y,z:p.z});}return true;}
 update(dt,intents=[]){if(this.done||dt<=0)return;dt=Math.min(dt,1/30);this.clock+=dt;for(const p of this.players){const a=intents[p.id]||{},boost=a.boost&&p.energy>1,speed=boost?13:8,drag=a.brake?7:2.5,wx=Math.sin(this.clock*.32+this.level)*(.2+this.difficulty*.12),wz=Math.cos(this.clock*.23)*.3;p.energy=clamp(p.energy+dt*(boost?-22:10),0,100);p.cooldown=Math.max(0,p.cooldown-dt);p.shield=Math.max(0,p.shield-dt);p.ringCooldown=Math.max(0,p.ringCooldown-dt);let x=clamp(a.x||0,-1,1),z=clamp(a.z||0,-1,1),mag=Math.max(1,Math.hypot(x,z));p.vx+=(x/mag*speed-p.vx)*Math.min(1,dt*drag)+wx*dt;p.vz+=(z/mag*speed-p.vz)*Math.min(1,dt*drag)+wz*dt;p.y=clamp(p.y+(a.alt||0)*dt*4,1.7,9);p.x=clamp(p.x+p.vx*dt,-18,18);p.z=clamp(p.z+p.vz*dt,-13,13);if(Math.hypot(p.vx,p.vz)>.3)p.angle=Math.atan2(p.vx,p.vz);for(const o of this.obstacles){const d=Math.hypot(p.x-o.x,p.z-o.z),r=o.r+.7;if(p.y<o.height+1&&d<r){const nx=(p.x-o.x)/(d||1),nz=(p.z-o.z)/(d||1);p.x=o.x+nx*r;p.z=o.z+nz*r;p.vx=nx*3;p.vz=nz*3;this.hit(p);}}for(let i=0;i<this.storms.length;i++){const s=this.storm(i);if(Math.hypot(p.x-s.x,p.z-s.z)<s.r+.6)this.hit(p);}for(const r of this.rings)if(!p.ringCooldown&&Math.hypot(p.x-r.x,p.z-r.z,p.y-r.y)<1.5){p.rings++;p.energy=100;p.ringCooldown=8;this.events.push({type:'ring',owner:p.id,x:p.x,y:p.y,z:p.z});}if(a.dock)this.dock(p.id);}if(this.players.every(p=>p.delivered>=this.goal)){this.done=true;this.won=true;}else if(this.clock>=this.limit)this.done=true;}
 storm(i){const s=this.storms[i];return{...s,x:s.x+Math.sin(this.clock*.4+i)*3,z:s.z+Math.cos(this.clock*.3+i)*2};}
 hit(p){if(p.shield)return;p.shield=1.8;p.hits++;p.hull--;this.events.push({type:'bump',owner:p.id,x:p.x,y:p.y,z:p.z});if(!p.hull){const h=HARBORS[this.job(p).source];Object.assign(p,{x:h.x,z:h.z,y:2.2,vx:0,vz:0,hull:3,carrying:false,energy:100});}}
 score(){return Math.max(0,this.players.reduce((n,p)=>n+p.delivered*350+p.rings*40-p.hits*25,0)+(this.won?Math.round((this.limit-this.clock)*3):0));}
}
